# ======================================================================== B1: S2 provenance / geometry
def _pin_with_stub(conn):
    o = next(o for o in conn["objects"] if o["kind"] == "PIN" and o["pin"]["stub"])
    return o, o["pin"]["stub"]


def _reject(conn, needle):
    with pytest.raises(writer.DocumentError) as e:
        writer.loads(rehash_conn(conn))                 # re-hashing a forged document does not help
    assert any(needle in p for p in e.value.problems), e.value.problems


def test_b1_valid_s2_lineage_is_accepted_on_load_and_against_the_page():
    pi, conn, syms = docs(chain("r0"))
    stubs = [o["pin"]["stub"] for o in conn["objects"] if o["kind"] == "PIN"]
    assert stubs and all(s is not None for s in stubs)
    assert writer.s2_problems(conn) == [] and symrec.audit_evidence(conn, syms, pi, LIB) == []
    for o in conn["objects"]:
        if o["kind"] == "PIN":
            ev = next(e for e in conn["evidence"] if e["id"] == "S2:" + o["id"][2:])
            assert ev["lineage"] == [f"geom:{o['pin']['stub']['prim']}"]
            t, b = o["pin"]["tip"], o["pin"]["base"]
            plen = ((t[0] - b[0]) ** 2 + (t[1] - b[1]) ** 2) ** 0.5
            assert 0 < o["pin"]["stub"]["tolerance"] <= max(S2_TAU_ABS_MAX, S2_REL_MAX * plen) + 1e-12


def test_b1_validation_promotes_nothing():
    # the states in the file are exactly detect_pins' states; a passing check does not change any of them
    sc = chain("r0")
    pi, cls, cl, built, res = sc.run()
    pi2, conn, syms = docs(sc)
    want = {f"p:{cr.cluster.id}:{k}": p.pos_state for cr in cl for k, p in enumerate(cr.pins)}
    assert {o["id"]: o["pin"]["pos_state"] for o in conn["objects"] if o["kind"] == "PIN"} == want


@pytest.mark.parametrize("scene", [chain("r0"), chain("dg"), crossing()], ids=lambda s: s.name)
def test_b1_existing_but_unrelated_primitive_is_rejected(scene):
    pi, conn, syms = docs(scene)
    o, st = _pin_with_stub(conn)
    other = next(p for p in conn["primitives"] if p["id"] != st["prim"]
                 and p["id"] not in {x["pin"]["stub"]["prim"] for x in conn["objects"] if x["kind"] == "PIN"})
    bad = copy.deepcopy(conn)
    bo = next(x for x in bad["objects"] if x["id"] == o["id"])
    bo["pin"]["stub"]["prim"] = other["id"]
    next(e for e in bad["evidence"] if e["id"] == "S2:" + o["id"][2:])["lineage"] = [f"geom:{other['id']}"]
    with pytest.raises(writer.DocumentError):
        writer.loads(rehash_conn(bad))
    # the page audit rejects it even when the file-level bbox check is not reached
    assert any("is not segment" in p or "outside the bbox" in p or "no segment" in p
               for p in symrec.audit_s2_against_page(bad, pi))
    # and the same forgery with the unrelated primitive's REAL segment does not span the pin
    q = next(q for q in pi.prims if q.id == other["id"])
    _, a, b = next(iter(q.segments()))
    bo["pin"]["stub"].update(a=list(map(float, a)), b=list(map(float, b)), segment=0)
    _reject(bad, "does not span base")


def test_b1_lineage_naming_another_primitive_than_the_stub_is_rejected():
    pi, conn, syms = docs(chain("r0"))
    o, st = _pin_with_stub(conn)
    bad = copy.deepcopy(conn)
    next(e for e in bad["evidence"] if e["id"] == "S2:" + o["id"][2:])["lineage"] = ["geom:3"]
    _reject(bad, "is not the stub primitive")


@pytest.mark.parametrize("end", ["a", "b"])
def test_b1_wrong_endpoint_is_rejected(end):
    pi, conn, syms = docs(chain("r0"))
    o, st = _pin_with_stub(conn)
    bad = copy.deepcopy(conn)
    s = next(x for x in bad["objects"] if x["id"] == o["id"])["pin"]["stub"]
    s[end] = [s[end][0] + 3 * s["tolerance"], s[end][1]]
    _reject(bad, "does not span base")


def test_b1_widened_tolerance_is_rejected():
    pi, conn, syms = docs(chain("r0"))
    o, st = _pin_with_stub(conn)
    bad = copy.deepcopy(conn)
    s = next(x for x in bad["objects"] if x["id"] == o["id"])["pin"]["stub"]
    s["tolerance"] = 1000.0
    s["b"] = [s["b"][0] + 50.0, s["b"][1]]
    _reject(bad, "wider than the policy")


def test_b1_reversed_geometry_is_explicit():
    pi, conn, syms = docs(chain("r0"))
    o, st = _pin_with_stub(conn)
    bad = copy.deepcopy(conn)
    s = next(x for x in bad["objects"] if x["id"] == o["id"])["pin"]["stub"]
    s["a"], s["b"] = s["b"], s["a"]                       # reversed, orientation label left as it was
    _reject(bad, "orientation recorded")
    s["orientation"] = "REVERSED" if st["orientation"] == "FORWARD" else "FORWARD"
    fixed = writer.loads(rehash_conn(bad))                # self-consistent in the file ...
    assert any("is not segment" in p for p in symrec.audit_s2_against_page(fixed, pi))   # ... not on the page


@pytest.mark.parametrize("field,value,needle", [
    ("a", ["x", 1.0], "malformed"), ("segment", -1, "malformed"), ("orientation", "SIDEWAYS", "malformed"),
    ("tolerance", 0.0, "malformed"), ("prim", "5", "malformed"), ("extra", 1, "malformed")])
def test_b1_malformed_stub_is_rejected(field, value, needle):
    pi, conn, syms = docs(chain("r0"))
    o, st = _pin_with_stub(conn)
    bad = copy.deepcopy(conn)
    next(x for x in bad["objects"] if x["id"] == o["id"])["pin"]["stub"][field] = value
    _reject(bad, needle)


def test_b1_degenerate_stub_is_rejected():
    pi, conn, syms = docs(chain("r0"))
    o, st = _pin_with_stub(conn)
    bad = copy.deepcopy(conn)
    s = next(x for x in bad["objects"] if x["id"] == o["id"])["pin"]["stub"]
    s["b"] = list(s["a"])
    _reject(bad, "degenerate")


